def transition(state, action, context, acquire):
    if state is None:
        state = {"actions": []}
    state["actions"].append(action)
    return state


def simulate(cand, actions):
    committed = {}
    pending = {"main": {}, "other": {}}
    total = {"main": 0, "other": 0}
    main_last = 0
    open_conn = None
    for a in actions:
        op = a.get("op")
        if op == "begin":
            if open_conn is None:
                c = a.get("connection", "main")
                if c != "other":
                    c = "main"
                open_conn = c
        elif op == "commit":
            if open_conn is not None:
                p = pending[open_conn]
                for k in p:
                    committed[k] = p[k]
                pending[open_conn] = {}
                open_conn = None
        elif op == "rollback":
            if open_conn is not None:
                pending[open_conn] = {}
                open_conn = None
        else:
            if open_conn is not None:
                conn = open_conn
            else:
                conn = a.get("connection", "main")
                if conn != "other":
                    conn = "main"
            p = pending[conn]
            key = a.get("key")
            exists = key in p or key in committed
            ch = 0
            fired = False
            if op == "put":
                v = a.get("value")
                if exists:
                    if cand["conflict"] == "ignore":
                        pass
                    elif cand["conflict"] == "replace":
                        p[key] = v
                        ch = 2
                        fired = True
                    else:
                        p[key] = v
                        ch = 1
                else:
                    p[key] = v
                    ch = 1
                    fired = True
            elif op == "update":
                if exists:
                    p[key] = a.get("value")
                    ch = 1
            elif op == "delete":
                if exists:
                    p.pop(key)
                    ch = 1
            total[conn] = total[conn] + ch
            if fired and cand["trigger"]:
                total[conn] = total[conn] + 1
            if conn == "main":
                main_last = ch
    if cand["channel"] == "changes":
        chan = main_last
    elif cand["channel"] == "total_main":
        chan = total["main"]
    else:
        chan = total["main"] + total["other"]
    s = 0
    for v in committed.values():
        s = s + v
    return {"channel": chan, "count": len(committed), "sum": s}


def consistent(hist, source_id):
    out = []
    for conflict in ["ignore", "replace", "upsert"]:
        for channel in ["changes", "total_main", "total_both"]:
            for trig in [False, True]:
                cand = {"conflict": conflict, "channel": channel, "trigger": trig}
                ok = True
                for r in hist:
                    if r.get("source_id") != source_id:
                        continue
                    obs = r.get("observed")
                    res = simulate(cand, r.get("actions", []))
                    if res["channel"] != obs.get("channel"):
                        ok = False
                    if res["count"] != obs.get("committed_count"):
                        ok = False
                    if res["sum"] != obs.get("committed_sum"):
                        ok = False
                if ok:
                    out.append(cand)
    return out


def readout(state, context, acquire):
    if state is None:
        state = {"actions": []}
    if "cands" not in state:
        hist = acquire("history")
        state["cands"] = consistent(hist, context.get("source_id"))
    goal = context.get("goal")
    vals = []
    for cand in state["cands"]:
        res = simulate(cand, context.get("actions", []))
        if goal == "channel":
            vals.append(res["channel"])
        elif goal == "committed_count":
            vals.append(res["count"])
        else:
            vals.append(res["sum"])
    if len(vals) == 0:
        return {"value": None, "unresolved": True}
    first = vals[0]
    for v in vals:
        if v != first:
            return {"value": None, "unresolved": True}
    return {"value": first, "unresolved": False}


def investigate(context, acquire):
    state = None
    for action in context["actions"]:
        state = transition(state, action, context, acquire)
    return readout(state, context, acquire)
